export interface PointBinding {
  elementId: string
  focus: number   // normalized position along the bound edge, signed (~ -1..1)
  gap: number     // distance kept between arrow tip and the bound shape
}
export interface ExcalidrawArrowElement extends ExcalidrawElementBase {
  type: 'arrow'
  points: [number, number][]
  startBinding: PointBinding | null
  endBinding: PointBinding | null
}
// a shape is 'bindable' if isBindableElement(el) is true; arrows bind TO those.

export interface SceneAPI {
  updateScene(scene: { elements: ExcalidrawElement[]; appState?: Partial<AppState> }): void
  getSceneElements(): readonly ExcalidrawElement[]
}
// updateScene replaces elements; the reconciler compares version + versionNonce
// to merge concurrent edits (higher version wins; nonce breaks ties).

// Eve renders custom payloads by storing them as a 'rectangle' with a
// customData: { kind: 'sticky-note', ... } field, then overlaying a React layer
// keyed by element.id. Excalidraw renders the rectangle; Eve paints the sticky body.
export function renderCustomOverlay(el) { if (el.customData?.kind) return <StickyNote el={el} /> }
